function routeAt(g){g=Math.max(0,Math.min(1265,g));for(let i=1;i<ROUTE.length;i++){const a=ROUTE[i-1],b=ROUTE[i];if(g<=b[2]){const t=(g-a[2])/(b[2]-a[2]||1);return[a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t]}}return ROUTE[ROUTE.length-1].slice(0,2)}
function routeSliceG(x,y){const a=Math.min(x,y),b=Math.max(x,y);const out=[routeAt(a)];ROUTE.forEach(r=>{if(r[2]>a&&r[2]<b)out.push([r[0],r[1]])});out.push(routeAt(b));return out}
