function derive(){
  const mO=placeMile(S.from),mD=placeMile(S.to),dir=mD>=mO?1:-1,lo=Math.min(mO,mD),hi=Math.max(mO,mD);
  const L=g=>dir>0?g-mO:mO-g,G=x=>dir>0?mO+x:mO-x;
  const inR=g=>g>=lo-0.5&&g<=hi+0.5;
  R={mO,mD,dir,lo,hi,T:hi-lo,L,G,inR};
  R.stops=STOPS.map((s,i)=>({id:"st"+i,g:s[0],local:L(s[0]),cat:s[1],name:s[2],desc:s[3],opt:!!s[4],lat:s[5],lon:s[6]})).filter(s=>inR(s.g)).sort((a,b)=>a.local-b.local);
  R.spots=Object.entries(SPOTS).filter(([,s])=>!s[8]||(s[8]==="nb")===(dir>0)).map(([id,s])=>({id,area:s[0],g:s[1],local:L(s[1]),cat:s[2],rest:!!AREAS[s[0]].restOnly})).filter(s=>s.local>5&&s.local<R.T-5);
  R.wx=WX.filter(w=>inR(w[0])).map(w=>({w,local:L(w[0])})).sort((a,b)=>a.local-b.local);
  R.towns=TOWNS.filter(t=>inR(t[0])).map(t=>[L(t[0]),t[1]]).sort((a,b)=>a[0]-b[0]);
  const ov=(a,b)=>Math.max(0,Math.min(hi,b)-Math.max(lo,a));
  R.caMi=ov(0,OR_LINE);R.orMi=ov(OR_LINE,1265);
  const po=routeAt(mO),pd=routeAt(mD);R.origin={name:S.from,lat:po[0],lon:po[1]};R.dest={name:S.to,lat:pd[0],lon:pd[1]};
}

/* ================= planner ================= */
function plan(){
  const T=R.T,days=[];
  if(T<1)return[{i:0,a:0,b:0,area:null,spot:null,H:0,over:false}];
  if(S.straight){days.push({i:0,a:0,b:T,area:null,spot:null,H:T/MPH,over:false});return days}
  let pos=0,i=0;
  while(pos<T-0.5&&i<25){
    const H=hoursFor(i),B=H*MPH,lim=pos+B+0.5;
    const forced=S.dayEnd[i];
    if(forced&&SPOTS[forced]){const lm=R.L(SPOTS[forced][1]);if(lm>pos+10&&lm<T-1){days.push({i,a:pos,b:lm,area:SPOTS[forced][0],spot:forced,H,over:lm-pos>B+0.5,forced:true});pos=lm;i++;continue}}
    if(T-pos<=B+0.5){days.push({i,a:pos,b:T,area:null,spot:null,H,over:false});break}
    const within=[],ahead=[];
    Object.keys(AREAS).filter(id=>!AREAS[id].restOnly).forEach(id=>{
      const opts=R.spots.filter(s=>s.area===id&&s.local>pos+15).sort((a,b)=>a.local-b.local);if(!opts.length)return;
      const pref=opts.find(s=>s.id===pickFor(id));
      if(pref&&pref.local<=lim)within.push(pref);
      else{const fit=opts.filter(s=>s.local<=lim);if(fit.length)within.push(fit[fit.length-1]);else ahead.push(pref||opts[0])}
    });
    within.sort((a,b)=>a.local-b.local);ahead.sort((a,b)=>a.local-b.local);
    const pick=within.length?within[within.length-1]:ahead[0];
    if(!pick){days.push({i,a:pos,b:T,area:null,spot:null,H,over:true});break}
    days.push({i,a:pos,b:pick.local,area:pick.area,spot:pick.id,H,over:!within.length});
    pos=pick.local;i++;
  }
  return days;
}
function dayOf(x){for(let i=0;i<PLAN.length;i++){const d=PLAN[i];if(x<=d.b+0.01&&(i===0||x>d.a))return i}return PLAN.length-1}
function itemSpots(){const set=new Set();PLAN.forEach(d=>{if(d.area)R.spots.forEach(s=>{if(s.area===d.area)set.add(s.id)})});if(S.straight)R.spots.filter(s=>s.cat==="truck").forEach(s=>set.add(s.id));return set}
function nearestRest(i){const d=PLAN[i];if(!d||!d.spot)return[];return R.spots.filter(s=>s.cat==="truck"&&s.id!==d.spot&&s.local>d.a+5).map(s=>({...s,off:s.local-d.b})).sort((a,b)=>Math.abs(a.off)-Math.abs(b.off)).slice(0,4)}
function activeSpots(){const set=itemSpots();PLAN.forEach((d,i)=>nearestRest(i).forEach(r=>set.add(r.id)));PLAN.forEach(d=>{if(d.area)R.spots.forEach(s=>{if(s.area===d.area)set.add(s.id)})});if(S.straight)R.spots.filter(s=>s.cat==="truck").forEach(s=>set.add(s.id));return set}
function buildItems(){
  const act=itemSpots(),out=PLAN.map(()=>[]);
  R.stops.forEach(s=>out[dayOf(s.local)].push({...s}));
  R.spots.forEach(s=>{if(!act.has(s.id))return;const sp=SPOTS[s.id];let di=PLAN.findIndex(d=>d.area===s.area);const nap=di<0;if(nap)di=dayOf(s.local);const tonight=!nap&&PLAN[di].spot===s.id;
    out[di].push({id:"sp-"+s.id,spot:s.id,g:s.g,local:s.local,cat:s.cat,name:sp[3],desc:sp[4],opt:!tonight,lat:sp[6],lon:sp[7],tonight,nap})});
  out[PLAN.length-1].push({id:"dest",g:R.mD,local:R.T,cat:"camp",name:R.dest.name,desc:"Destination. You made it.",opt:false,lat:R.dest.lat,lon:R.dest.lon,dest:true});
  out.forEach(a=>a.sort((x,y)=>x.local-y.local));return out;
}

/* ================= fuel, Anker & shower, Plan B ================= */
const FILLPRICE={"Costco Ontario, Guasti Rd":4.89,"Costco Woodland":4.95,"Costco Redding, Bechelli Ln":4.55,"Costco Central Point (Medford)":3.99,"Costco Albany":3.75,"Costco Clackamas, off I-205":3.79};
function fillPrice(f){const st=GAS.street;const statePx=f.g<OR_LINE?st.ca:st.or;if(S.gas==="street"||!FILLPRICE[f.name])return statePx;return FILLPRICE[f.name]}
function dayFuelCost(d){const a=Math.min(R.G(d.a),R.G(d.b)),b=Math.max(R.G(d.a),R.G(d.b));const ca=Math.max(0,Math.min(b,OR_LINE)-a),or=Math.max(0,b-Math.max(a,OR_LINE));const g=GAS[S.gas];return{gal:(ca+or)/S.mpg,cost:ca/S.mpg*g.ca+or/S.mpg*g.or}}
function simulateFuel(){
  const fills=R.stops.filter(s=>(s.cat==="costco"||s.cat==="fuel")&&!s.opt&&s.local>0.5&&s.local<R.T-0.5).sort((a,b)=>a.local-b.local);
  const evts=[...fills.map(f=>({x:f.local,f})),{x:R.T,end:true}];
  let gal=TANK,last=0;const warn=[],at=[],buys=[];
  evts.forEach(e=>{const need=(e.x-last)/S.mpg;const remain=gal-need;
    if(remain<RESERVE){const lowAt=last+Math.max(0,(gal-RESERVE))*S.mpg;const opt=R.stops.filter(s=>(s.cat==="costco"||s.cat==="fuel")&&s.opt&&s.local>last&&s.local<=lowAt).pop();
      warn.push({x:lowAt,empty:last+gal*S.mpg,next:e.f?e.f.name:R.dest.name,fix:opt?opt.name:null,short:need-gal+RESERVE})}
    at.push({x:e.x,arrive:remain,name:e.f?e.f.name:R.dest.name});if(e.f&&remain>0)buys.push({x:e.x,name:e.f.name,gal:TANK-remain,price:fillPrice(e.f)});gal=e.end?remain:TANK;last=e.x});
  const tankAt=x=>{let g=TANK,l=0;for(const e of evts){if(e.x>=x)return g-(x-l)/S.mpg;g=e.end?g:TANK;l=e.x}return g};
  return{fills,warn,at,tankAt,buys};
}
function simulateCamp(){
  let pct=100,since=0;
  return PLAN.map(d=>{const drive=(d.b-d.a)/MPH;pct=Math.min(100,pct+drive*TRUCK_W/ANKER_WH*100);
    if(!d.spot)return{end:true,pct};
    const power=SPOTS[d.spot][2]==="camp";
    if(power){since=0;pct=100;return{bed:100,morning:100,since,power}}
    const bed=pct;pct=Math.max(0,pct-S.blanket*BLANKET_H/ANKER_WH*100);since++;
    return{bed,morning:pct,since,power,nudge:pct<25||since>=2}});
}
function planB(i){
  const d=PLAN[i],items=DAYITEMS[i];if(!d||S.straight)return null;
  const passes=items.filter(it=>it.cat==="pass"&&it.local>d.a+10&&it.local<=d.b+0.5);
  for(const p of passes){const before=R.spots.filter(s=>s.local>d.a+15&&s.local<p.local-3).sort((a,b)=>a.local-b.local);if(before.length){const s=before[before.length-1];return{pass:p,spot:s.id,local:s.local}}}
  return null;
}

