function canShorten(d){return R.spots.some(s=>s.local>d.a+15&&s.local<d.b-1)}
// Try day i's limit in 0.5 h steps (dir +1 longer, -1 shorter) and return the first one where plan() actually
// moves the day's end ({H, day, name}), or null. Simulates the day without a Plan B stop, as longer/shorter
// clear it. plan() only reads R and S, and S is restored before returning. Cached on d (PLAN is rebuilt on change).
function stepHours(i,d,dir){const k=dir>0?"_up":"_dn";if(k in d)return d[k];
  const has=o=>Object.prototype.hasOwnProperty.call(o,i),hadH=has(S.dayHours),oldH=S.dayHours[i],hadE=has(S.dayEnd),oldE=S.dayEnd[i];let res=null;
  try{delete S.dayEnd[i];for(let H=d.H+dir*0.5;dir>0?H<=16:H>=0.5;H+=dir*0.5){S.dayHours[i]=H;const p=plan()[i];
    if(p&&(dir>0?p.b>d.b+1:p.b<d.b-1)){res={H,day:p,name:p.spot?shortName(p.spot):R.dest.name};break}}}
  finally{if(hadH)S.dayHours[i]=oldH;else delete S.dayHours[i];if(hadE)S.dayEnd[i]=oldE;else delete S.dayEnd[i]}
  return d[k]=res}
const canLonger=(i,d)=>!!d.area&&!!stepHours(i,d,1);
function shorter(i,d){if(!canShorten(d))return;const r=stepHours(i,d,-1);if(!r)return;delete S.dayEnd[i];store.set("dayEnd",S.dayEnd);setDayHours(i,r.H)}
function longer(i,d){if(!d.area)return;const r=stepHours(i,d,1);if(!r)return;delete S.dayEnd[i];store.set("dayEnd",S.dayEnd);setDayHours(i,r.H)}
function setDayHours(i,v){v=Math.min(16,Math.max(0.5,Math.round(v*2)/2));if(v===S.hours)delete S.dayHours[i];else S.dayHours[i]=v;store.set("dayHours",S.dayHours);rebuild()}
function refocus(id){const e=document.getElementById(id);if(e)e.focus({preventScroll:true})}
const ETA={};
function etas(){
  PLAN.forEach((d,i)=>{const t=toMin(S.starts[i]||"07:30");let dwell=0;
    DAYITEMS[i].forEach(it=>{const m=it.local-d.a;const at=t+Math.max(m,0)/MPH*60+dwell;ETA[it.id]=at;const e=document.getElementById("eta-"+it.id);if(e)e.textContent=i===0&&it.local<0.5?"start":"≈"+fmtTime(at);if(!it.opt&&!it.spot&&DWELL[it.cat]&&m>0&&m<d.b-d.a)dwell+=DWELL[it.cat]});
    const arrive=t+(d.b-d.a)/MPH*60+dwell,end=ptOf(i,true),sun=sunTimes(dateFor(i),end.lat,end.lon),ssBase=sun.set,ss=ssBase+1440*Math.floor(arrive/1440),diff=ss-arrive,b=document.getElementById("arr"+i);d.arrive=arrive;d.sunset=ssBase;d.dwell=dwell;const sr=document.getElementById("sun"+i);if(sr){const st=sunTimes(dateFor(i),ptOf(i,false).lat,ptOf(i,false).lon);sr.textContent=`Sunrise ≈${fmtTime(st.rise)} · sunset ≈${fmtTime(ssBase)}`}
    if(!b)return;
    if(S.straight){b.className="arr late";b.textContent=`Arrive ≈${fmtTime(arrive)} with no sleep stops`;return}
    b.className="arr "+(diff>=30?"ok":"late");b.textContent=diff>=0?`Arrive ≈${fmtTime(arrive)} · ${Math.floor(diff/60)}h${String(Math.round(diff%60)).padStart(2,"0")} before dark`:`Arrive ≈${fmtTime(arrive)} · after sunset (≈${fmtTime(ssBase)})`;
  });
}

/* ================= header & sheet ================= */
function renderHeader(){
  $("#title").textContent=`${S.from}, ${placeState(S.from)} to ${S.to}, ${placeState(S.to)}`;
  const nav=$("#dests");nav.innerHTML="";PLAN.forEach((d,i)=>{const a=document.createElement("a");a.href="#day-"+(i+1);a.innerHTML=`<span>${esc(ptOf(i,true).name)}</span><span>${Math.round(d.b)}</span>`;a.addEventListener("click",e=>{e.preventDefault();selectDay(i+1,true)});nav.appendChild(a)});
  const L0=dlabel(0),L1=dlabel(PLAN.length-1);
  $("#subline").textContent=S.straight?`${L0.dow} ${L0.date} · straight shot, ≈${hrs(R.T)} moving`:`${L0.dow} ${L0.date} → ${L1.dow} ${L1.date} · ${Object.keys(S.dayHours).length?"custom hours per day":"up to "+S.hours+" h a day"} · ${PLAN.filter(d=>d.area).length} nights · I-5${R.hi>1025?" & I-84":""}`;
  $("#shield-dir").textContent=R.dir>0?"NORTH":"SOUTH";
  const dn=$("#daynav");dn.innerHTML="";[["All",0],...PLAN.map((d,i)=>[`${dlabel(i).dow} · ${ptOf(i,true).name}`,i+1])].forEach(([t,n])=>{const b=document.createElement("button");b.type="button";b.dataset.day=n;b.textContent=t;b.setAttribute("aria-pressed",n===curDay);b.addEventListener("click",()=>selectDay(n,true));dn.appendChild(b)});
}
function renderSheet(){
  const lines=[];const L0=dlabel(0);
  lines.push(`${S.from} → ${S.to} · ${Math.round(R.T)} mi · ${PLAN.length} day(s) · leaving ${L0.dow} ${L0.date}`);
  lines.push(`Road conditions: Caltrans 1-800-427-7623 / quickmap.dot.ca.gov · Oregon 511 / tripcheck.com`);
  PLAN.forEach((d,i)=>{const L=dlabel(i),a=ptOf(i,false),b=ptOf(i,true);lines.push("");lines.push(`DAY ${i+1} · ${L.dow} ${L.date} · ${a.name} → ${b.name} · ${Math.round(d.b-d.a)} mi · ≈${hrs(d.b-d.a)} driving`);
    lines.push(`  Leave ${fmtTime(toMin(S.starts[i]||"07:30"))} · arrive ≈${fmtTime(d.arrive)} · sunset ≈${fmtTime(d.sunset)}`);
    DAYITEMS[i].forEach(it=>{if(it.nap||(it.spot&&!it.tonight))return;const tag=it.dest?" [DESTINATION]":it.tonight?" [TONIGHT]":it.opt?" (optional)":"";lines.push(`  mi ${String(Math.round(it.local-d.a)).padStart(3)} · ≈${fmtTime(ETA[it.id]??0).padEnd(8)} · ${it.name}${tag}`);if(it.tonight||it.cat==="pass")lines.push(`        ${it.desc}`)});
    const alts=DAYITEMS[i].filter(it=>it.spot&&!it.tonight&&!it.nap).map(it=>`${it.name} (mi ${Math.round(it.local-d.a)})`);if(alts.length)lines.push(`  Backups tonight: ${alts.join("; ")}`);
    const nr=nearestRest(i);if(nr.length)lines.push(`  Closest rest areas: ${nr.map(r=>`${SPOTS[r.id][3]} (${Math.round(Math.abs(r.off))} mi ${r.off<0?"before":"past"})`).join("; ")}`);
    const pb=planB(i);if(pb)lines.push(`  Plan B: if ${pb.pass.name} is closed or chains are required, stop at ${shortName(pb.spot)} (mi ${Math.round(pb.local-d.a)}).`);
    FUEL.warn.filter(w=>w.x>=d.a&&w.x<=d.b).forEach(w=>lines.push(`  FUEL: low near mi ${Math.round(w.x-d.a)} before ${w.next}. ${w.fix?"Stop at "+w.fix+".":"Top up ≈"+Math.ceil(w.short)+" gal before then."}`));
    {const fc=dayFuelCost(d);const bs=FUEL.buys.filter(bb=>bb.x>d.a+0.5&&bb.x<=d.b+0.5);lines.push(`  Fuel: ≈$${Math.round(fc.cost)} burned today${bs.length?` · at the pump ≈$${Math.round(bs.reduce((t,bb)=>t+bb.gal*bb.price,0))} (${bs.map(bb=>bb.name.replace(/, .*| \(.*\)/,'')).join(', ')})`:''}`)}
    const hs=hospFor(d);if(hs.length)lines.push(`  Nearest ER: ${hs.map(h=>h[0]).join('; ')} · 911`);
    if(d.spot){const m=moonInfo(dateFor(i));lines.push(`  Night sky: ${m.name}, ${m.ill}% lit`)}
    const tr=TRACK[i];if(tr&&!tr.end)lines.push(`  Anker ${Math.round(tr.bed)}% at bedtime → ${Math.round(tr.morning)}% by morning · ${tr.power?"shower tonight":tr.since+" night(s) since a shower"}`);
  });
  $("#sheet").textContent=lines.join("\n");
}

/* ================= selection ================= */
let curDay=0,selId=null;
function clearSel(){selId=null;Object.values(pinEls).forEach(p=>p.classList.remove("sel"));Object.values(listItems).forEach(l=>l.classList.remove("sel"));Object.values(stripMarks).forEach(m=>m.classList.remove("sel"));document.querySelectorAll("[data-show]").forEach(b=>b.textContent="Show on map");$("#detail").innerHTML=`<div class="dk">Stop details</div><p>Tap any pin on the map or a stop in the list.</p>`}
function select(id,src){
  if(selId===id&&src==="map"){clearSel();return}
  selId=id;document.querySelectorAll("[data-show]").forEach(b=>b.textContent=b.dataset.show===id?"Hide on map":"Show on map");
  Object.values(pinEls).forEach(p=>p.classList.remove("sel"));Object.values(listItems).forEach(l=>l.classList.remove("sel"));Object.values(stripMarks).forEach(m=>m.classList.remove("sel"));
  pinEls[id]?.classList.add("sel");listItems[id]?.classList.add("sel");stripMarks[id]?.classList.add("sel");if(pinEls[id])gPins.appendChild(pinEls[id]);
  const di=DAYITEMS.findIndex(a=>a.some(it=>it.id===id));const it=di>=0?DAYITEMS[di].find(x=>x.id===id):null;
  let name,desc,cat,la,lo,mile;if(it){({name,desc,cat,lat:la,lon:lo}=it);mile=Math.round(it.local)}else if(id.startsWith("sp-")){const s=SPOTS[id.slice(3)];[,,cat,name,desc,,la,lo]=s;mile=Math.round(R.L(s[1]))}else{const s=STOPS[+id.slice(2)];[,cat,name,desc,,la,lo]=s;mile=Math.round(R.L(s[0]))}
  const L=di>=0?dlabel(di):null;
  $("#detail").innerHTML=`<div class="dk">${L?`Day ${di+1} · ${L.dow} · `:""}${CAT[cat].t} · mile ${mile} from ${esc(S.from)}</div><b>${esc(name)}</b><p>${esc(desc)}</p><div class="dbtns"><button type="button" id="dgo">${src==="map"?"Show in day list ↓":"Center on map"}</button><button type="button" id="dclear">✕ Clear highlight</button></div>`;
  $("#dclear").addEventListener("click",clearSel);
  $("#dgo").addEventListener("click",()=>{if(src==="map"&&listItems[id]){listItems[id].scrollIntoView({behavior:"smooth",block:"center"});listItems[id].focus({preventScroll:true})}else centerOn(la,lo)});
  if(src!=="map")centerOn(la,lo);else if(di>=0)selectDay(di+1,false,true);
}
function centerOn(la,lo){const[x,y]=P(la,lo);const w=Math.min(VB.w,240),h=w*1070/500;animVB(clampVB({x:x-w/2,y:y-h/2,w,h}))}
function hoverDay(n){segEls.forEach((s,i)=>s.line.setAttribute("stroke",n===i+1||curDay===i+1?"var(--hi)":"var(--route)"))}
function selectDay(n,zoom,noScroll){
  curDay=n;document.querySelectorAll("#daynav button").forEach(b=>b.setAttribute("aria-pressed",+b.dataset.day===n));
  segEls.forEach((s,i)=>{const on=n===0||n===i+1;s.line.setAttribute("stroke",n&&on?"var(--hi)":"var(--route)");s.g.style.opacity=on?1:.35});
  document.querySelectorAll(".day").forEach(d=>d.classList.toggle("active",n!==0&&d.id==="day-"+n));
  if(zoom&&n&&segEls[n-1])fitPts(segEls[n-1].s);if(zoom&&n===0)animVB({...FULL});
  if(n&&!noScroll){document.getElementById("day-"+n)?.scrollIntoView({behavior:matchMedia("(prefers-reduced-motion:reduce)").matches?"auto":"smooth",block:"start"});try{history.replaceState(null,"","#day-"+n)}catch(e){}}
}

/* ================= init ================= */
function autoLeave(){PLAN.forEach((d,i)=>{const end=ptOf(i,true),st=ptOf(i,false);const set=sunTimes(dateFor(i),end.lat,end.lon).set,rise=sunTimes(dateFor(i),st.lat,st.lon).rise;const need=(d.b-d.a)/MPH*60+(d.dwell||0);let t=set-60-need;t=Math.max(t,rise-30,300);t=Math.min(t,10*60);t=Math.floor(t/15)*15;S.starts[i]=`${String(Math.floor(t/60)).padStart(2,"0")}:${String(t%60).padStart(2,"0")}`});store.set("starts",S.starts);renderDays();renderSheet();$("#leavemsg").textContent="Leave times set: arrive about an hour before sunset where the drive allows."}
function buildPack(){const host=$("#packlist");host.innerHTML="";let total=0;
  const cats=[...PACK.map(([c])=>c)];S.customPack.forEach(it=>{if(!cats.includes(it.cat))cats.push(it.cat)});
  const save=()=>{store.set("customPack",S.customPack);store.set("pack",S.pack)};
  cats.forEach((cat,ci)=>{const g=document.createElement("div");g.className="pg";g.innerHTML=`<div class="gk">${esc(cat)}</div>`;const ul=document.createElement("ul");ul.className="checklist";
    const base=(PACK.find(p=>p[0]===cat)||[cat,[]])[1].map((t,ii)=>({key:`${PACK.findIndex(p=>p[0]===cat)}-${ii}`,text:t,custom:false}));
    const mine=S.customPack.filter(it=>it.cat===cat).map(it=>({key:"c-"+it.id,text:it.text,custom:true,id:it.id}));
    [...base,...mine].forEach(it=>{total++;const li=document.createElement("li");li.innerHTML=`<label><input type="checkbox" ${S.pack.includes(it.key)?"checked":""}><span>${esc(it.text)}</span></label>${it.custom?`<button type="button" class="linkb pdel" aria-label="Remove ${esc(it.text)}">✕</button>`:""}`;
      li.querySelector("input").addEventListener("change",e=>{if(e.target.checked){if(!S.pack.includes(it.key))S.pack.push(it.key)}else S.pack=S.pack.filter(x=>x!==it.key);save();packProg(total)});
      const del=li.querySelector(".pdel");if(del)del.addEventListener("click",()=>{S.customPack=S.customPack.filter(x=>x.id!==it.id);S.pack=S.pack.filter(x=>x!==it.key);save();buildPack()});
      ul.appendChild(li)});
    g.appendChild(ul);
    const fm=document.createElement("form");fm.className="padd";fm.innerHTML=`<label class="sr" for="padd${ci}">Add an item to ${esc(cat)}</label><input id="padd${ci}" type="text" placeholder="Add to ${esc(cat)}…" maxlength="80"><button type="submit" class="linkb">+ Add</button>`;
    fm.addEventListener("submit",e=>{e.preventDefault();const inp=fm.querySelector("input");const t=inp.value.trim();if(!t)return;S.customPack.push({id:Date.now().toString(36)+Math.random().toString(36).slice(2,5),cat,text:t});save();buildPack();document.getElementById(`padd${ci}`)?.focus()});
    g.appendChild(fm);host.appendChild(g)});
  const nf=document.createElement("form");nf.className="padd newcat";nf.innerHTML=`<label class="sr" for="pcat">New category</label><input id="pcat" type="text" placeholder="New category (e.g. Dog gear)" maxlength="40"><label class="sr" for="pcatitem">First item</label><input id="pcatitem" type="text" placeholder="First item" maxlength="80"><button type="submit" class="btn">Add category</button>`;
  nf.addEventListener("submit",e=>{e.preventDefault();const c=$("#pcat").value.trim(),t=$("#pcatitem").value.trim();if(!c||!t){(c?$("#pcatitem"):$("#pcat")).focus();return}S.customPack.push({id:Date.now().toString(36),cat:c,text:t});save();buildPack()});
  host.appendChild(nf);packProg(total)}
function packProg(total){const n=Math.min(S.pack.length,total);$("#pack-n").textContent=`${n} of ${total} packed`;$("#pack-bar").style.width=(n/total*100)+"%"}
let EST={gas:0,camp:0,food:0};
function renderExpenses(){const tb=$("#exp-list");tb.innerHTML="";const sums={gas:0,food:0,camp:0,other:0};S.expenses.forEach((e,k)=>{sums[e.cat]=(sums[e.cat]||0)+e.amt;const tr=document.createElement("tr");tr.innerHTML=`<td>${esc(e.day)}</td><td>${esc(e.cat)}</td><td class="num">$${e.amt.toFixed(2)}</td><td>${esc(e.note||"")}</td><td><button type="button" class="linkb" aria-label="Delete expense">✕</button></td>`;tr.querySelector("button").addEventListener("click",()=>{S.expenses.splice(k,1);store.set("expenses",S.expenses);renderExpenses()});tb.appendChild(tr)});
  const spent=Object.values(sums).reduce((a,b)=>a+b,0),est=EST.gas+EST.camp+EST.food;
  $("#exp-sum").innerHTML=[["Gas",sums.gas,EST.gas],["Food",sums.food,EST.food],["Camping",sums.camp,EST.camp],["Other",sums.other,null]].map(([l,a,e])=>`<div class="es"><span class="k">${l}</span><b>$${Math.round(a)}</b><span class="n">${e!=null?`of ≈$${Math.round(e)} planned`:""}</span></div>`).join("")+`<div class="es tot"><span class="k">Total</span><b>$${Math.round(spent)}</b><span class="n">of ≈$${Math.round(est)} planned · ${spent<=est?"$"+Math.round(est-spent)+" left":"$"+Math.round(spent-est)+" over"}</span></div>`}
function buildExpenses(){const sel=$("#exp-day");const fill=()=>{sel.innerHTML="";PLAN.forEach((d,i)=>{const L=dlabel(i);sel.add(new Option(`Day ${i+1} · ${L.dow}`,`Day ${i+1}`))})};fill();
  $("#exp-form").addEventListener("submit",e=>{e.preventDefault();const amt=parseFloat($("#exp-amt").value);if(!(amt>0)){$("#exp-amt").focus();return}S.expenses.push({day:sel.value,cat:$("#exp-cat").value,amt,note:$("#exp-note").value.trim()});store.set("expenses",S.expenses);$("#exp-amt").value="";$("#exp-note").value="";renderExpenses();$("#exp-amt").focus()});
  return fill}
let refillExpDays=()=>{};
function refreshLight(){FUEL=simulateFuel();TRACK=simulateCamp();recalc();renderDays();renderSheet()}
function rebuild(){derive();PLAN=plan();if(curDay>PLAN.length)curDay=0;DAYITEMS=buildItems();FUEL=simulateFuel();TRACK=simulateCamp();buildNights();recalc();renderHeader();renderDays();renderMapDynamic();renderSheet();refillExpDays();if($("#exp-list"))renderExpenses()}
buildStatic();buildChecklist();buildFilters();buildMapStatic();bindMapUI();buildPack();$("#autoleave").addEventListener("click",autoLeave);
rebuild();refillExpDays=buildExpenses();renderExpenses();setVB({...FULL});
function fromHash(){const m=/^#day-(\d+)$/.exec(location.hash);if(m&&+m[1]<=PLAN.length)selectDay(+m[1],true,false)}
window.addEventListener("hashchange",fromHash);fromHash();

